import itertools

def generate_adjacency_matrix(N):
    # Generate all permutations of N natural numbers from 1 to N*(N-1)/2
    max_edge_value = N * (N - 1) // 2
    for perm in itertools.permutations(range(1, max_edge_value + 1)):
        matrix = [[0] * N for _ in range(N)]
        edge_index = 0
        for i in range(N):
            for j in range(i + 1, N):
                matrix[i][j] = perm[edge_index]
                matrix[j][i] = perm[edge_index]
                edge_index += 1

        # Check if the matrix satisfies the conditions
        if all(0 <= matrix[i][j] <= 1000 for i in range(N) for j in range(N) if i < j):
            if all(matrix[i][j] == matrix[j][i] for i in range(N) for j in range(N) if i < j):
                if all(matrix[i][i] == 0 for i in range(N)):
                    if len(set(itertools.chain.from_iterable(matrix))) == len(perm):
                        if all(sum(matrix[i][j] for j in range(N) if i < j) == sum(matrix[j][i] for j in range(N) if i < j) for i in range(N)):
                            return matrix
    return None

